import{_t as e,it as t,n,rt as r}from"./chunks/framework.D2cFUyj2.js";var i=JSON.parse(`{"title":"空间分析","description":"","frontmatter":{},"headers":[{"level":2,"title":"1. 如何进入空间分析","slug":"_1-如何进入空间分析","link":"#_1-如何进入空间分析","children":[]},{"level":2,"title":"2. 界面布局与视觉呈现","slug":"_2-界面布局与视觉呈现","link":"#_2-界面布局与视觉呈现","children":[{"level":3,"title":"左侧：Treemap 矩形树状图","slug":"左侧-treemap-矩形树状图","link":"#左侧-treemap-矩形树状图","children":[]},{"level":3,"title":"右侧：降序统计列表","slug":"右侧-降序统计列表","link":"#右侧-降序统计列表","children":[]}]},{"level":2,"title":"3. 交互导航与快捷操作","slug":"_3-交互导航与快捷操作","link":"#_3-交互导航与快捷操作","children":[]},{"level":2,"title":"4. 统计口径与实时索引同步","slug":"_4-统计口径与实时索引同步","link":"#_4-统计口径与实时索引同步","children":[{"level":3,"title":"统计范围与口径说明","slug":"统计范围与口径说明","link":"#统计范围与口径说明","children":[]},{"level":3,"title":"实时变更监听与自愈","slug":"实时变更监听与自愈","link":"#实时变更监听与自愈","children":[]}]}],"relativePath":"zh-CN/user-guide/space-analyzer.md","filePath":"zh-CN/user-guide/space-analyzer.md","lastUpdated":1791112464000}`),a={name:`zh-CN/user-guide/space-analyzer.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="空间分析" tabindex="-1">空间分析 <a class="header-anchor" href="#空间分析" aria-label="Permalink to “空间分析”">​</a></h1><p>Lertaro 内置了磁盘与文件夹<strong>空间分析器（Space Analyzer）</strong>。与传统的磁盘扫描分析工具不同，它直接复用 Lertaro 在后台已构建的内存索引树，无需进行漫长耗时的全盘物理扫描，即便是包含数百万文件的多磁盘环境也能做到秒级呈现。</p><h2 id="_1-如何进入空间分析" tabindex="-1">1. 如何进入空间分析 <a class="header-anchor" href="#_1-如何进入空间分析" aria-label="Permalink to “1. 如何进入空间分析”">​</a></h2><ul><li><strong>自动展示</strong>：打开 Lertaro 完整搜索主窗口（<code>Ctrl+F</code>）且<strong>搜索框保持为空</strong>时，空间分析会自动作为首页呈现。</li><li><strong>即时切换</strong>：在搜索框中键入任意字符将立刻切换为常规搜索结果列表；按 <code>Escape</code> 或退格清空搜索框后，将立即返回空间分析视图。</li></ul><h2 id="_2-界面布局与视觉呈现" tabindex="-1">2. 界面布局与视觉呈现 <a class="header-anchor" href="#_2-界面布局与视觉呈现" aria-label="Permalink to “2. 界面布局与视觉呈现”">​</a></h2><p>空间分析采用左右双栏联动设计，直观反映各目录与文件的空间占比：</p><h3 id="左侧-treemap-矩形树状图" tabindex="-1">左侧：Treemap 矩形树状图 <a class="header-anchor" href="#左侧-treemap-矩形树状图" aria-label="Permalink to “左侧：Treemap 矩形树状图”">​</a></h3><ul><li><strong>面积直观表达</strong>：体积越大的文件夹或文件占据越大的矩形面积。</li><li><strong>色彩与明暗层级</strong>：不同深浅明暗表达在当前父目录中的相对比重，通过特定的边框样式清晰区分文件夹与普通文件。</li></ul><h3 id="右侧-降序统计列表" tabindex="-1">右侧：降序统计列表 <a class="header-anchor" href="#右侧-降序统计列表" aria-label="Permalink to “右侧：降序统计列表”">​</a></h3><ul><li><strong>体积降序排列</strong>：将当前层级的子项目从大到小排列，便于快速发现占用空间的“大头”。</li><li><strong>占比进度条</strong>：每行条目下方配有细长占比条，直观反映该项目占当前视图总容量的百分比。</li><li><strong>双向联动高亮</strong>：在左侧矩形卡片或右侧列表中选中任意一项，另一侧都会同步高亮聚焦。</li><li><strong>长文件名自动滚动</strong>：超出显示宽度的长名称会在鼠标悬停或选中时自动滚动展开，不再使用遮挡界面的浮窗提示。</li></ul><h2 id="_3-交互导航与快捷操作" tabindex="-1">3. 交互导航与快捷操作 <a class="header-anchor" href="#_3-交互导航与快捷操作" aria-label="Permalink to “3. 交互导航与快捷操作”">​</a></h2><ul><li><strong>下钻与返回</strong>： <ul><li><strong>进入目录</strong>：鼠标左键双击左侧矩形卡片或右侧列表项，即可下钻深入该目录查看内部结构。</li><li><strong>返回上级</strong>：点击顶部导航栏的“向上”箭头，或直接点击面包屑路径上的任意父级节点即可返回。</li></ul></li><li><strong>上下文动作菜单</strong>：在任意卡片或列表行上右键单击，即可展开与主搜索结果完全相同的<strong>动作菜单</strong>（直接打开、复制完整路径、在资源管理器中定位、移入回收站或彻底删除）。</li><li><strong>文件管理器中键定位</strong>：在卡片或列表项上点击鼠标中键，将直接在已配置的文件管理器中打开并定位该目标。</li><li><strong>即时预览联动</strong>：选中项目后按下 <code>Alt+P</code> 即可展开 QuickLook 预览面板，随后选中的所有条目都会自动跟随预览。</li></ul><h2 id="_4-统计口径与实时索引同步" tabindex="-1">4. 统计口径与实时索引同步 <a class="header-anchor" href="#_4-统计口径与实时索引同步" aria-label="Permalink to “4. 统计口径与实时索引同步”">​</a></h2><h3 id="统计范围与口径说明" tabindex="-1">统计范围与口径说明 <a class="header-anchor" href="#统计范围与口径说明" aria-label="Permalink to “统计范围与口径说明”">​</a></h3><ul><li><strong>基于已有索引</strong>：空间分析仅汇总 Lertaro 当前已启用索引中的条目，不会额外发起磁盘 I/O 遍历。被排除规则忽略的文件不会计入统计。</li><li><strong>逻辑大小统计</strong>：界面展示的是文件的逻辑实际大小，硬链接数据仅计入一次，避免容量虚高。</li><li><strong>隐藏与系统文件</strong>：隐藏文件会正常参与统计和展示；系统文件大小会合并计入其所在父级文件夹的总容量中。</li></ul><h3 id="实时变更监听与自愈" tabindex="-1">实时变更监听与自愈 <a class="header-anchor" href="#实时变更监听与自愈" aria-label="Permalink to “实时变更监听与自愈”">​</a></h3><ul><li><strong>实时刷新</strong>：当后台文件发生增删改动时，空间分析会自动接收索引变更通知，并经过批量防抖合并后平滑更新当前视图。</li><li><strong>路径自愈回退</strong>：若当前正在浏览的文件夹或其上级目录被外部程序删除、重命名或从索引中移除，空间分析会自动回退到第一个依然有效的上层可用目录，确保界面绝不崩溃或显示异常。</li></ul>`,17)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};